--- upstream/app/javascript/controllers/copy_to_clipboard_controller.js
+++ src/Campfire/wwwroot/assets/controllers/copy_to_clipboard_controller-62ea12e6.js
@@ -1,7 +1,7 @@
 import { Controller } from "@hotwired/stimulus"

 export default class extends Controller {
-  static values = { content: String }
+  static values = { content: String, url: String }
   static classes = [ "success" ]

   async copy(event) {
@@ -9,7 +9,7 @@
     this.reset()

     try {
-      await navigator.clipboard.writeText(this.contentValue)
+      await navigator.clipboard.writeText(this.#text)
       this.element.classList.add(this.successClass)
     } catch {}
   }
@@ -19,6 +19,12 @@
     this.#forceReflow()
   }

+  // A url value is a path, made absolute against the page it's on, so cached markup that is
+  // shared by every request doesn't have to carry the request's host.
+  get #text() {
+    return this.hasUrlValue ? new URL(this.urlValue, document.baseURI).href : this.contentValue
+  }
+
   #forceReflow() {
     this.element.offsetWidth
   }

--- upstream/app/javascript/lib/autocomplete/base_autocomplete_handler.js
+++ src/Campfire/wwwroot/assets/lib/autocomplete/base_autocomplete_handler-51cdc033.js
@@ -120,7 +120,7 @@

   #fetchAutocompletables(url) {
     if (url) {
-      return fetch(url, { as: "json" }).then(response => response.json())
+      return fetch(url, { headers: { Accept: "application/json" } }).then(response => response.json())
     } else {
       return Promise.resolve()
     }
